"""Пошаговые разборы главы 2.2: core_spawn.c для Windows и для macOS и Linux, run_child.c и новые части brain.py.

Номера строк — по файлам tools/src22 (у brain.py — по фрагменту BRAIN_PART из ch22). Оформление — trace_html из walk11."""
from walk11 import like, trace_html


def build(hl, hl_py, src, brain_part):
    W = {}

    W['win'] = trace_html('core_spawn.c', 'win',
        'запустить программу по списку аргументов и дождаться её кода завершения. <code>core_spawn</code> собирает из списка командную строку и вызывает <code>CreateProcessW</code>, <code>core_wait</code> ждёт процесс и забирает код.',
        [('1-5', 'Подключить заголовочные файлы',
          '<ul class="words"><li><code>string.h</code> — <code>strchr</code>, поиск символа в строке;</li>'
          '<li><code>windows.h</code> — функции и типы WinAPI;</li>'
          '<li><code>core.h</code> — <code>struct core_child</code> и объявления функций ядра.</li></ul>'
          '<p><code>CMD_MAX</code> — сколько символов UTF-16 помещается в командную строку ядра, 1024.</p>'),
         ('7-11', 'Начать core_spawn',
          '<p><code>cmd</code> — командная строка в UTF-16: в этой кодировке её принимает <code>CreateProcessW</code>. <code>used</code> — сколько символов уже записано. <code>STARTUPINFOW si</code> — как показать окно нового процесса; здесь всё по умолчанию. <code>PROCESS_INFORMATION pi</code> — сюда Windows запишет ответ: номер процесса, номер потока и два дескриптора.</p>'),
         ('13-14', 'Проверить параметры',
          '<p>Без списка аргументов, без имени программы или без места для ответа запускать нечего — код 87, <code>ERROR_INVALID_PARAMETER</code>.</p>'),
         ('15-29', 'Собрать командную строку',
          '<p>В Windows программа получает аргументы одной строкой, и разбирает её сама. Поэтому список <code>argv</code> склеивается через пробел. Аргумент с пробелом берётся в кавычки, иначе он развалится на два.</p>'
          '<ul class="words"><li><code>strchr(argv[i], \' \')</code> — есть ли в аргументе пробел;</li>'
          '<li><code>used + 3 &gt;= CMD_MAX</code> — места не осталось даже на пробел и две кавычки: код 122;</li>'
          '<li><code>MultiByteToWideChar(CP_UTF8, …)</code> — перевод аргумента из UTF-8 в UTF-16 прямо в <code>cmd</code>, как в главе 1.1. Функция возвращает число символов вместе с завершающим нулём, поэтому <code>used</code> растёт на <code>n - 1</code>.</li></ul>'
          '<p>Из <code>["cmd", "/c", "exit 7"]</code> получается <code>cmd /c "exit 7"</code>.</p>'
          + like('Анкету заполняют печатными буквами в одну строку, а слова из нескольких частей берут в кавычки, чтобы их не разделили.')),
         ('32-35', 'Создать процесс',
          '<p><code>ZeroMemory</code> обнуляет <code>si</code>, а <code>si.cb</code> сообщает Windows размер структуры. Параметры <code>CreateProcessW</code> по порядку:</p>'
          '<ul class="words"><li><code>NULL</code> — путь к программе не задан: Windows возьмёт первое слово командной строки, допишет <code>.exe</code> и будет искать файл в папке программы-родителя, в текущей папке, в системных папках Windows и затем в папках из <code>PATH</code>;</li>'
          '<li><code>cmd</code> — командная строка. Функция может её менять, поэтому строка лежит в массиве: строковую константу менять нельзя;</li>'
          '<li><code>NULL, NULL</code> — права доступа к процессу и потоку по умолчанию;</li>'
          '<li><code>FALSE</code> — ребёнок не получает открытые дескрипторы родителя;</li>'
          '<li><code>0</code> — без особых флагов: ребёнок пишет в ту же консоль;</li>'
          '<li><code>NULL, NULL</code> — переменные окружения и текущая папка родителя;</li>'
          '<li><code>&amp;si, &amp;pi</code> — как показать окно и куда записать ответ.</li></ul>'
          '<p>Если процесс не создан, функция возвращает 0. Причину даёт <code>GetLastError</code>: 2 — файла программы нет.</p>'),
         ('36-39', 'Сохранить ответ',
          '<p>Windows вернула два дескриптора. <span class="term">Дескриптор</span> (handle) — номер в таблице открытых объектов процесса, через него с объектом работают функции WinAPI. Дескриптор главного потока ядру не нужен, и <code>CloseHandle</code> сразу его закрывает. Дескриптор процесса нужен, чтобы дождаться процесса и забрать код, поэтому он сохраняется в <code>out-&gt;handle</code>. <code>(int64_t)(intptr_t)</code> — перевод адреса-дескриптора в число той же ширины, что поле структуры.</p>'),
         ('42-46', 'Начать core_wait',
          '<p>Без дескриптора процесса ждать нечего: <code>handle == 0</code> значит, что процесс не запускался или уже дождались. Дескриптор возвращается из числа обратно в <code>HANDLE</code>.</p>'),
         ('47-52', 'Дождаться процесса',
          '<p><code>WaitForSingleObject</code> ставит поток на паузу, пока процесс не завершится или не выйдет время. Отрицательное время в ядре значит «ждать сколько потребуется» — <code>INFINITE</code>. Ответ <code>WAIT_TIMEOUT</code> (258) — время вышло, процесс ещё работает, и дескриптор остаётся открытым: его можно ждать снова. Любой другой ответ, кроме <code>WAIT_OBJECT_0</code>, — ошибка.</p>'),
         ('53-58', 'Забрать код и закрыть дескриптор',
          '<p><code>GetExitCodeProcess</code> читает код завершения. После этого дескриптор процесса закрывается, и Windows может удалить запись о процессе. <code>child-&gt;handle = 0</code> отмечает, что ждать больше нечего.</p>')],
        [('argv', 'список аргументов'), ('cmd', 'одна строка UTF-16'), ('CreateProcessW', 'процесс и дескриптор'),
         ('WaitForSingleObject', 'ждать'), ('GetExitCodeProcess', 'код')],
        hl(src('win')))

    W['posix'] = trace_html('core_spawn.c', 'mac linux',
        'запустить программу по списку аргументов и дождаться её кода завершения. <code>core_spawn</code> вызывает <code>posix_spawnp</code>, <code>core_wait</code> забирает код вызовом <code>waitpid</code>.',
        [('1-5', 'Подключить заголовочные файлы',
          '<ul class="words"><li><code>errno.h</code> — коды ошибок и <code>errno</code>;</li>'
          '<li><code>spawn.h</code> — <code>posix_spawnp</code>;</li>'
          '<li><code>sys/wait.h</code> — <code>waitpid</code> и разбор ответа: <code>WIFEXITED</code>, <code>WEXITSTATUS</code>;</li>'
          '<li><code>time.h</code> — <code>nanosleep</code>, пауза между проверками.</li></ul>'),
         ('7', 'Объявить переменные окружения',
          '<p><code>environ</code> — массив строк «имя=значение» с переменными окружения процесса. Он есть в каждой программе, но в заголовочных файлах не объявлен, поэтому строку <code>extern</code> пишут сами. Ядро передаёт его ребёнку, и тот получает те же переменные, что у родителя.</p>'),
         ('9-13', 'Начать core_spawn и проверить параметры',
          '<p>Без списка аргументов, без имени программы или без места для ответа — код 22, <code>EINVAL</code>.</p>'),
         ('14-16', 'Запустить программу',
          '<p><code>posix_spawnp</code> создаёт процесс и загружает в него программу одним вызовом — те же копия и <code>execve</code>, что в ЛР 5. Буква <code>p</code> в конце значит, что имя ищется по папкам <code>PATH</code>, как у <code>env</code>.</p>'
          '<ul class="words"><li><code>&amp;pid</code> — сюда запишется номер нового процесса;</li>'
          '<li><code>argv[0]</code> — имя программы;</li>'
          '<li><code>NULL, NULL</code> — без перенаправления файлов и без особых настроек;</li>'
          '<li><code>argv</code> — весь список аргументов, его последний элемент — <code>NULL</code>;</li>'
          '<li><code>environ</code> — переменные окружения.</li></ul>'
          '<p>Функция возвращает код ошибки сама, без <code>errno</code>: 2 — программы нет.</p>'),
         ('17-19', 'Сохранить ответ',
          '<p>В macOS и Linux процесс называют по номеру, отдельного дескриптора нет, поэтому <code>handle</code> равен 0.</p>'),
         ('22-28', 'Начать core_wait',
          '<p><code>step</code> — пауза 10 мс между проверками: 0 секунд и 10 000 000 наносекунд. <code>waited</code> — сколько миллисекунд уже прошло. Без номера процесса ждать нечего — <code>EINVAL</code>.</p>'),
         ('29-39', 'Проверять, завершился ли ребёнок',
          '<p><code>waitpid(pid, &amp;status, WNOHANG)</code> спрашивает ядро о ребёнке. С флагом <code>WNOHANG</code> вызов отвечает сразу:</p>'
          '<ul class="words"><li>номер ребёнка — он завершился, код записан в <code>status</code>, и ядро удалило запись о нём;</li>'
          '<li>0 — ребёнок ещё работает;</li>'
          '<li>−1 — ошибка, например <code>ECHILD</code>: такого ребёнка нет.</li></ul>'
          '<p>Пока ребёнок работает, цикл спит 10 мс и спрашивает снова. Когда прошло <code>timeout_ms</code>, функция возвращает <code>ETIMEDOUT</code> — 60 в macOS, 110 в Linux.</p>'
          + like('Курьер звонит в дверь каждые 10 секунд и после минуты уходит с запиской «зайду позже».')),
         ('40-44', 'Разобрать ответ',
          '<p><code>status</code> — число, в котором ядро упаковало, как завершился процесс. <code>WIFEXITED</code> — завершился сам, тогда <code>WEXITSTATUS</code> даёт код. Иначе процесс завершён сигналом, и ядро записывает <code>128 + номер сигнала</code>, как это делают оболочки: сигнал 9 даёт 137.</p>')],
        [('argv', 'список аргументов'), ('posix_spawnp', 'процесс по номеру'), ('waitpid', 'спросить каждые 10 мс'), ('status', 'код')],
        hl(src('posix')))

    W['run'] = trace_html('run_child.c', 'win mac linux',
        'проверить ядро без Python: запустить программу из командной строки, напечатать номер нового процесса и его код завершения или ошибку.',
        [('1-4', 'Подключить заголовочные файлы',
          '<p><code>inttypes.h</code> — формат <code>PRId64</code> для <code>int64_t</code>, <code>stdlib.h</code> — <code>atoi</code>.</p>'),
         ('6-13', 'Проверить командную строку',
          '<p>Программе нужны хотя бы два параметра: время ожидания в миллисекундах и имя программы. Например, <code>run_child 5000 sh -c "exit 7"</code>: <code>argv[1]</code> — 5000, с <code>argv[2]</code> начинается запускаемая программа.</p>'),
         ('14-19', 'Запустить',
          '<p><code>argv + 2</code> — адрес третьего элемента: ядро получает список с имени программы, без <code>run_child</code> и времени. Список уже кончается <code>NULL</code>, так устроен <code>argv</code> любой программы на C.</p>'),
         ('20-24', 'Дождаться',
          '<p><code>atoi(argv[1])</code> — время из командной строки числом. Если время вышло, программа сообщает код и номер процесса, который ещё работает.</p>'),
         ('25-26', 'Напечатать код',
          '<p>Номер процесса и его код завершения. Сама <code>run_child</code> завершается с кодом 0.</p>')],
        [('argv[1]', 'время'), ('core_spawn', 'запуск'), ('core_wait', 'ожидание'), ('печать', 'pid и код')],
        hl(src('run')))

    W['brain'] = trace_html('brain.py · новые части', 'win mac linux',
        'дать мозгу две функции: <code>spawn</code> запускает программу через ядро, <code>wait</code> ждёт её и возвращает код завершения или поднимает исключение.',
        [('1-5', 'Описать struct core_child',
          '<p>Те же два поля по 8 байт, что в <code>core.h</code>: номер процесса и дескриптор.</p>'),
         ('7-10', 'Описать функции ядра',
          '<p><code>ctypes.POINTER(ctypes.c_char_p)</code> — адрес массива строк, это <code>char *const argv[]</code> на стороне C. Остальные типы — как в главе 2.1.</p>'),
         ('12-18', 'spawn: список Python → argv',
          '<p><code>ctypes.c_char_p * (len(args) + 1)</code> — тип «массив строк на одно место больше списка». Последнее место — <code>None</code>, в C это <code>NULL</code>, конец списка. Строки Python переводятся в байты UTF-8 через <code>encode</code>. Из <code>["python", "-c", "…"]</code> получается массив из четырёх элементов, последний — пустой адрес.</p>'
          '<p>Если ядро вернуло не 0, функция поднимает <code>OSError</code> с кодом и текстом, как <code>get_info</code>.</p>'),
         ('20-25', 'wait: ждать и вернуть код',
          '<p><code>timeout_ms=-1</code> по умолчанию — ждать сколько потребуется. Код завершения ребёнка ядро записывает в <code>code</code>, функция возвращает его обычным числом Python.</p>')],
        [('["python", …]', 'список'), ('argv', 'массив с NULL'), ('core_spawn', 'запуск'), ('core_wait', 'код')],
        hl_py(brain_part))
    return W
